import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"常見問題對照表","description":"MiniTavern 連接 Ollama/LM Studio 測連失敗、超時、CORS、防火牆等常見問題對照與處理。","frontmatter":{"title":"常見問題對照表","description":"MiniTavern 連接 Ollama/LM Studio 測連失敗、超時、CORS、防火牆等常見問題對照與處理。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"常見問題對照表 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 連接 Ollama/LM Studio 測連失敗、超時、CORS、防火牆等常見問題對照與處理。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/troubleshoot"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/troubleshoot"}]]},"headers":[],"relativePath":"zh-TW/troubleshoot.md","filePath":"zh-TW/troubleshoot.md","lastUpdated":1787224147000}'),o={name:"zh-TW/troubleshoot.md"};function l(i,t,h,n,c,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="常見問題對照表" tabindex="-1">常見問題對照表 <a class="header-anchor" href="#常見問題對照表" aria-label="Permalink to &quot;常見問題對照表&quot;">​</a></h1><p>按現象查找；仍不行可在 App <strong>設置 → 幫助與反饋 → 問題反饋</strong> 提交（可附截圖與問題日誌），或用 <strong>反饋郵箱</strong>。請儘量寫清：系統、工具（Ollama / LM Studio / KoboldCPP 等）、Base URL（可打碼 IP 後兩段）、報錯原文。</p><h2 id="連接-測連" tabindex="-1">連接 / 測連 <a class="header-anchor" href="#連接-測連" aria-label="Permalink to &quot;連接 / 測連&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>可能原因</th><th>處理</th></tr></thead><tbody><tr><td>連接超時</td><td>不在同一 Wi‑Fi、防火牆攔端口、服務未監聽 <code>0.0.0.0</code></td><td>確認同網；放行端口；按各工具「開服務 / 局域網」章節操作</td></tr><tr><td>立刻失敗 / 無法連接</td><td>IP 錯、端口錯、服務沒開</td><td>電腦瀏覽器先打開 <code>http://IP:端口/v1/models</code>；核對 Base URL</td></tr><tr><td>填了 localhost 仍失敗</td><td>手機上的 localhost 是手機自己</td><td>改成電腦局域網 IP</td></tr><tr><td>401 / 密鑰錯誤</td><td>少數本地棧校驗 Key</td><td>填任意非空佔位，或按該工具文檔關閉鑑權</td></tr><tr><td>404 / 模型不存在</td><td>模型名與本地不一致</td><td><code>ollama list</code> 或各工具 <code>/v1/models</code> 複製 <strong>完整 id</strong></td></tr><tr><td>有響應但聊天空白/報錯</td><td>兼容性、超時過短、模型未加載</td><td>增大超時；確認模型已 load；換較小模型驗證通路</td></tr></tbody></table><h2 id="網絡與系統" tabindex="-1">網絡與系統 <a class="header-anchor" href="#網絡與系統" aria-label="Permalink to &quot;網絡與系統&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>可能原因</th><th>處理</th></tr></thead><tbody><tr><td>電腦能連、手機不能</td><td>訪客 Wi‑Fi 隔離、AP 隔離</td><td>改用主網絡；臨時用手機熱點讓電腦接入再試</td></tr><tr><td>偶發斷開</td><td>電腦休眠、IP 變化</td><td>禁止休眠；重查 IP 並更新連接</td></tr><tr><td>VPN 開啟後異常</td><td>分流/虛擬網卡</td><td>測試時先關 VPN 或排除局域網</td></tr></tbody></table><h2 id="url-寫法" tabindex="-1">URL 寫法 <a class="header-anchor" href="#url-寫法" aria-label="Permalink to &quot;URL 寫法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>正確示例</th><th>錯誤示例</th></tr></thead><tbody><tr><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://localhost:11434/v1</code></td></tr><tr><td><code>http://192.168.1.8:1234/v1</code></td><td><code>http://192.168.1.8:1234/v1/chat/completions</code></td></tr><tr><td><code>http://192.168.1.8:5001/v1</code></td><td><code>https://192.168.1.8:11434/v1</code>（本地未配證書時不要強行 https）</td></tr><tr><td><code>http://192.168.1.8:8080/v1</code></td><td></td></tr></tbody></table><h2 id="http-明文" tabindex="-1">HTTP 明文 <a class="header-anchor" href="#http-明文" aria-label="Permalink to &quot;HTTP 明文&quot;">​</a></h2><p>MiniTavern <strong>Android</strong> 已允許明文 HTTP（局域網常用）。若仍被攔：</p><ul><li>確認 Base URL 是 <code>http://</code> 而非錯誤協議</li><li>確認系統/廠商網絡保護未攔截局域網</li><li>iOS 若遇 ATS 限制，優先保證使用文檔中的局域網地址；仍失敗請反饋系統版本與報錯</li></ul><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>瀏覽器網頁才常受 CORS 限制；<strong>原生 App 直連 API 一般不受 CORS 影響</strong>。若你在電腦瀏覽器裡測前端頁面失敗，不代表 MiniTavern 會失敗——請以 App 內測連為準。</p><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>處理</th></tr></thead><tbody><tr><td>首字極慢</td><td>換更小量化/更小參數；確認在用 GPU</td></tr><tr><td>生成中途卡住</td><td>增大超時；關其它佔顯存程序；看電腦端日誌是否 OOM</td></tr></tbody></table><h2 id="相關鏈接" tabindex="-1">相關鏈接 <a class="header-anchor" href="#相關鏈接" aria-label="Permalink to &quot;相關鏈接&quot;">​</a></h2><ul><li><a href="./manual/errors">使用手冊 · 錯誤代碼</a>（測連 / 聊天 API 報錯）</li><li><a href="./quickstart">30 分鐘通關</a></li><li><a href="./local/tools">工具總覽</a> · <a href="./local/models">推薦模型</a></li><li><a href="./ollama/lan">Ollama 局域網</a></li><li><a href="./lmstudio/server">LM Studio Local Server</a></li><li><a href="./koboldcpp/server">KoboldCPP API</a></li><li><a href="./llamacpp/server">llama.cpp server</a></li><li><a href="./connect-app/minitavern">MiniTavern 配置</a></li></ul>',17)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
